CREATE OR REPLACE FUNCTION public.claim_own_role(_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF; IF _role <> 'student' THEN RAISE EXCEPTION 'Faculty and administrator access must be granted by a department administrator'; END IF; IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid()) THEN RAISE EXCEPTION 'A role has already been assigned to this account'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),_role); END; $$;